 if(in_array($view,['integrations','audit'],true)&&!$manage)respond(403,['error'=>'admin_required']);
 $feature=['jobs'=>'commands','integrations'=>'integrations','releases'=>'updates'][$view]??null;if($feature&&!v3Enabled(db(),$feature))respond(503,['error'=>'feature_disabled']);
 if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
  try{$result=v3Mutate(db(),$actor,$_POST);if(($_POST['action']??'')==='token')$secret=$result;elseif(($_POST['action']??'')==='launch')$target=$result;else{header('Location: v3.php?'.http_build_query(['view'=>$view,'saved'=>'1']),true,303);exit;}}catch(InvalidArgumentException|DomainException $e){http_response_code(400);$error=$e->getMessage();}
