 $deviceSort=['hostname'=>'c.hostname','agent_version'=>'c.agent_version','last_seen'=>'d.last_control_at'];$sort=$f['sort']?:'hostname';if($view==='devices'&&!isset($deviceSort[$sort]))throw new InvalidArgumentException('Ugyldig sortering.');$deviceOrder=($deviceSort[$sort]??'c.hostname').' '.($f['direction']==='desc'?'DESC':'ASC').',a.id';
 $rows=[];
 if($view==='devices'){$q=db()->prepare('SELECT a.id,a.customer_id,a.enabled,c.hostname,c.agent_version,d.updates_enabled,COALESCE(d.commands_enabled,1) AS commands_enabled,d.teamviewer_id,d.vnc_host,d.vnc_port,d.last_control_at,d.reported_version FROM inv_agents a LEFT JOIN inv_computers c ON c.agent_id=a.id LEFT JOIN inv_v3_devices d ON d.agent_id=a.id WHERE '.$where.' ORDER BY '.$deviceOrder.' LIMIT 51 OFFSET '.$offset);$q->execute($params);$rows=$q->fetchAll();}
 if($view==='jobs'){$q=db()->prepare('SELECT j.*,c.hostname FROM inv_v3_jobs j JOIN inv_agents a ON a.id=j.agent_id LEFT JOIN inv_computers c ON c.agent_id=a.id WHERE '.$where.' ORDER BY j.created_at DESC,j.id DESC LIMIT 51 OFFSET '.$offset);$q->execute($params);$rows=$q->fetchAll();}
 if($view==='integrations'){[$scope,$p]=v2Tenant($actor,'customer_id');$q=db()->prepare('SELECT id,customer_id,label,created_at,expires_at,revoked_at,last_used_at FROM inv_v3_tokens WHERE '.$scope.' ORDER BY created_at DESC,id LIMIT 51 OFFSET '.$offset);$q->execute($p);$rows=$q->fetchAll();}
 if($view==='releases')$rows=db()->query('SELECT id,version,platform,architecture,enabled,created_at,JSON_UNQUOTE(JSON_EXTRACT(manifest,\'$.expires_at\')) AS expires_at FROM inv_v3_releases ORDER BY created_at DESC,id LIMIT 51 OFFSET '.$offset)->fetchAll();
 if($view==='audit'){[$scope,$p]=v2Tenant($actor,'customer_id');$q=db()->prepare('SELECT * FROM inv_v3_audit WHERE '.$scope.' ORDER BY id DESC LIMIT 51 OFFSET '.$offset);$q->execute($p);$rows=$q->fetchAll();}
 $more=count($rows)>50;$rows=array_slice($rows,0,50);$flags=db()->query("SELECT name,value FROM inv_settings WHERE name LIKE 'v3_%'")->fetchAll(PDO::FETCH_KEY_PAIR);
}catch(InvalidArgumentException){respond(400,['error'=>'invalid_request']);}catch(Throwable $e){error_log('Inventory V3 page: '.get_class($e));respond(503,['error'=>'v3_unavailable']);}
function h(mixed $v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
