<?php if(in_array($view,['devices','jobs'],true)):?><form method="get" class="list-controls"><input type="hidden" name="view" value="<?=h($view)?>"><label>Søg computer<input name="q" type="search" value="<?=h($f['q'])?>"></label><label>Kunde<select name="customer"><option value="">Alle tilgængelige</option><?php foreach($customers as $c):?><option value="<?=h($c['id'])?>" <?=(string)$c['id']===$f['customer']?'selected':''?>><?=h($c['name'])?></option><?php endforeach ?></select></label><?php if($view==='devices'):?><label>Sortér efter<select name="sort"><?php foreach(['hostname'=>'Computernavn','agent_version'=>'Agentversion','last_seen'=>'Sidste kontrolkontakt'] as $sortKey=>$sortLabel):?><option value="<?=h($sortKey)?>" <?=$sort===$sortKey?'selected':''?>><?=h($sortLabel)?></option><?php endforeach ?></select></label><label>Retning<select name="direction"><option value="asc" <?=$f['direction']==='asc'?'selected':''?>>Stigende</option><option value="desc" <?=$f['direction']==='desc'?'selected':''?>>Faldende</option></select></label><?php endif ?><button>Søg og filtrér</button></form><?php endif ?>
<?php if($view==='devices'):?><p>Agent 3.0 kræves til fjernopgaver og automatiske opdateringer. Agenten kontakter selv serveren hvert minut; en offline enhed modtager opgaven, når den vender tilbage. Opdatering aktiveres pr. enhed. TeamViewer/VNC skal allerede være konfigureret på computerne.</p>
<?php foreach($rows as $r):?><details class="panel"><summary><?=h($r['hostname']?:$r['id'])?> · <?=h($names[(int)$r['customer_id']]??$r['customer_id'])?> · agent <?=h($r['agent_version']??'afventer scanning')?></summary><p><a href="./?id=<?=h($r['id'])?>">Se inventar</a> · <a href="?view=jobs&amp;agent=<?=h($r['id'])?>">Se fjernopgaver</a> · kontrolkontakt <?=h($r['last_control_at']??'ikke modtaget')?> UTC</p>
<?php if($manage):?>
<?php if(v3Enabled(db(),'commands')):?><form method="post"><?php fields('job',$r['id']);?><input type="hidden" name="request_key" value="<?=h(bin2hex(random_bytes(32)))?>"><label>Fjernopgave<select name="kind"><option value="scan_now">Scan og send nyt inventar</option><option value="flush_queue">Send ventende scanninger</option></select></label><button>Opret opgave</button></form><?php endif ?>
